-- piece : 98 ligne(s) de referentiel.
-- Rejouable : la table ne se remplit que si elle est vide. Rien n'est efface.
-- Produit depuis la base de reference, ne pas modifier a la main.

IF NOT EXISTS (SELECT 1 FROM dbo.[piece])
BEGIN
    SET IDENTITY_INSERT dbo.[piece] ON;
    SET IDENTITY_INSERT dbo.[piece] OFF;
    PRINT 'piece : ' + CAST(@@ROWCOUNT AS VARCHAR(10)) + ' ligne(s) chargee(s).';
END
ELSE PRINT 'piece : deja chargee, rien a faire.';
GO
